function playDistinctAlertTone(kind,choice,preview=false){if((!preview&&!alertSoundEnabled)||!audioContext||audioContext.state==="suspended")return;const sounds={"chime-1":{wave:"sine",notes:[[660,.12],[880,.14],[1120,.2]]},"chime-2":{wave:"triangle",notes:[[784,.13],[988,.13],[1318,.24]]},"chime-3":{wave:"sine",notes:[[523,.18],[659,.18],[784,.28]]},"bell-1":{wave:"triangle",notes:[[1046,.12],[784,.24],[1046,.3]]},"bell-2":{wave:"sine",notes:[[880,.28],[1174,.32]]},"pulse-1":{wave:"square",notes:[[740,.1],[740,.1],[988,.2]]},"urgent-1":{wave:"sawtooth",notes:[[520,.16],[390,.2],[520,.16],[390,.24]]},"urgent-2":{wave:"square",notes:[[440,.22],[330,.28],[440,.22],[330,.28]]},"marimba-1":{wave:"triangle",notes:[[523,.11],[659,.11],[784,.32]]},"glass-1":{wave:"sine",notes:[[1568,.22],[1174,.16],[1760,.34]]},"sonar-1":{wave:"sine",notes:[[392,.34],[784,.34],[1174,.42]]},"woodblock-1":{wave:"square",notes:[[330,.07],[330,.07],[494,.07],[330,.07]]},"arpeggio-1":{wave:"triangle",notes:[[440,.09],[554,.09],[659,.09],[880,.3]]},"digital-1":{wave:"square",notes:[[988,.07],[0,.06],[1318,.07],[0,.06],[1568,.22]]},"low-bell-1":{wave:"triangle",notes:[[392,.25],[494,.25],[392,.42]]}};const sound=sounds[choice]||sounds[kind==="delay"?"urgent-2":"chime-1"];try{let offset=0;const now=audioContext.currentTime;sound.notes.forEach(([frequency,duration])=>{if(frequency>0){const oscillator=audioContext.createOscillator(),gain=audioContext.createGain();oscillator.type=sound.wave;oscillator.frequency.setValueAtTime(frequency,now+offset);gain.gain.setValueAtTime(.0001,now+offset);gain.gain.exponentialRampToValueAtTime(.22,now+offset+.015);gain.gain.setValueAtTime(.22,now+offset+duration*.5);gain.gain.exponentialRampToValueAtTime(.0001,now+offset+duration);oscillator.connect(gain);gain.connect(audioContext.destination);oscillator.start(now+offset);oscillator.stop(now+offset+duration+.02);}offset+=duration+.075;});}catch(error){console.warn("TCC alert tone unavailable:",error);}}
function showNewOrderAlert(order,reminder=false){showDesktopOrderNotification(order,reminder);let toast=document.querySelector(".new-order-alert");if(!toast){toast=document.createElement("div");toast.className="new-order-alert";toast.setAttribute("role","alert");document.body.append(toast);}toast.textContent=reminder?"⚠ Order still waiting · "+order.order_number+" has been in New for 2 minutes. Please accept or reject it.":(order.parent_order_id?"Continuation order received · ":"New order received · ")+order.order_number+(order.parent_order_id?" · linked to "+(allOrders.find(x=>x.id===order.parent_order_id)?.order_number||"previous order"):"")+(order.customer_name?" · "+order.customer_name:"");toast.classList.add("visible");clearTimeout(toast._hideTimer);toast._hideTimer=setTimeout(()=>toast.classList.remove("visible"),9000);}
