async function loadOrders(){const loadStartedAt=Date.now();try{let incoming=[];if(viewingTrash){const [trashData,activeData]=await Promise.all([request("archived-orders"),request("orders")]);incoming=trashData.orders||[];activeOrders=activeData.orders||[];seenOrderIds=new Set(activeOrders.map(order=>order.id));ordersInitialized=true;}else{const data=await request("orders");incoming=data.orders||[];const now=Date.now(),newIds=new Set(incoming.filter(order=>order.status==="new").map(order=>order.id));for(const id of newOrderReminderAt.keys())if(!newIds.has(id))newOrderReminderAt.delete(id);for(const order of incoming){if(order.status!=="new")continue;const createdAt=Date.parse(order.created_at)||now;if(!newOrderReminderAt.has(order.id))newOrderReminderAt.set(order.id,createdAt+120000);if(now>=newOrderReminderAt.get(order.id)){newOrderReminderAt.set(order.id,now+120000);}}if(ordersInitialized){const fresh=incoming.filter(order=>!seenOrderIds.has(order.id)&&order.status==="new");if(fresh.length)fresh.slice(0,3).forEach(showNewOrderAlert);}seenOrderIds=new Set(incoming.map(order=>order.id));ordersInitialized=true;activeOrders=incoming;orderUpdateCursor=new Date(Date.now()-2000).toISOString();}allOrders=incoming;if(!orderNotificationCursor)orderNotificationCursor=new Date(loadStartedAt-1000).toISOString();$("#dashboardError").textContent="";$("#lastUpdated").textContent="Last updated "+new Date().toLocaleTimeString("en-IN");updateStats();renderOrders();}catch(error){if(/log in/i.test(error.message)){token="";localStorage.removeItem(TOKEN_KEY);showLogin();}else $("#dashboardError").textContent=error.message;}}
async function pollOrderUpdates(){if(!token||!ordersInitialized||orderUpdateBusy||viewingTrash)return;orderUpdateBusy=true;const startedAt=Date.now();try{const since=orderUpdateCursor||new Date(startedAt-30000).toISOString(),data=await request("orders-updates",{query:{since}}),updates=Array.isArray(data.orders)?data.orders:[];if(updates.length){const merged=new Map(allOrders.map(order=>[order.id,order]));updates.forEach(order=>{if(order.archived_at)merged.delete(order.id);else merged.set(order.id,order);});allOrders=[...merged.values()].sort((a,b)=>(Date.parse(b.created_at)||0)-(Date.parse(a.created_at)||0));activeOrders=allOrders;const newIds=new Set(allOrders.filter(order=>order.status==="new").map(order=>order.id));for(const id of newOrderReminderAt.keys())if(!newIds.has(id))newOrderReminderAt.delete(id);const now=Date.now();for(const order of allOrders){if(order.status!=="new")continue;const createdAt=Date.parse(order.created_at)||now;if(!newOrderReminderAt.has(order.id))newOrderReminderAt.set(order.id,createdAt+120000);if(now>=newOrderReminderAt.get(order.id)){newOrderReminderAt.set(order.id,now+120000);}}updateStats();renderOrders();$("#lastUpdated").textContent="Last updated "+new Date().toLocaleTimeString("en-IN");}orderUpdateCursor=new Date(startedAt-2000).toISOString();}catch(error){if(/log in/i.test(error.message)){token="";localStorage.removeItem(TOKEN_KEY);showLogin();}else console.warn("Unable to refresh changed orders",error);}finally{orderUpdateBusy=false;}}
async function pollNewOrders(){if(!token||!ordersInitialized||notificationPollBusy||viewingTrash)return;notificationPollBusy=true;const pollStartedAt=Date.now();try{const since=orderNotificationCursor||new Date(pollStartedAt-30000).toISOString(),data=await request("new-order-notifications",{query:{since}}),incoming=Array.isArray(data.orders)?data.orders:[],fresh=incoming.filter(order=>order.id&&!seenOrderIds.has(order.id));if(fresh.length){fresh.forEach(order=>showNewOrderAlert(order));const merged=new Map(allOrders.map(order=>[order.id,order]));fresh.forEach(order=>{merged.set(order.id,order);seenOrderIds.add(order.id);});allOrders=[...merged.values()].sort((a,b)=>(Date.parse(b.created_at)||0)-(Date.parse(a.created_at)||0));activeOrders=allOrders.filter(order=>!order.archived_at);updateStats();renderOrders();}orderNotificationCursor=new Date(pollStartedAt).toISOString();}catch(error){if(/log in/i.test(error.message)){token="";localStorage.removeItem(TOKEN_KEY);showLogin();}else console.warn("Unable to check for new orders",error);}finally{notificationPollBusy=false;}}
function updateStats(){const today=localDateKey(new Date()),rows=activeOrders.filter(o=>localDateKey(new Date(o.created_at))===today);$("#newCount").textContent=rows.filter(o=>o.status==="new").length;$("#progressCount").textContent=rows.filter(o=>["accepted","preparing"].includes(o.status)).length;$("#readyCompletedCount").textContent=rows.filter(o=>["ready","completed"].includes(o.status)).length;}
function formatElapsed(ms){const seconds=Math.max(0,Math.floor(ms/1000)),h=Math.floor(seconds/3600),m=Math.floor((seconds%3600)/60),s=seconds%60;return h>0?String(h).padStart(2,"0")+":"+String(m).padStart(2,"0")+":"+String(s).padStart(2,"0"):String(m).padStart(2,"0")+":"+String(s).padStart(2,"0");}
