function localDateKey(date){return date.getFullYear()+"-"+String(date.getMonth()+1).padStart(2,"0")+"-"+String(date.getDate()).padStart(2,"0");}
function filteredOrders(){const period=$("#periodFilter").value,now=new Date(),today=localDateKey(now);let from=null,to=null;if(period==="today"){from=today;to=today;}else if(period==="yesterday"){const d=new Date(now);d.setDate(d.getDate()-1);from=to=localDateKey(d);}else if(["7days","15days","30days","90days"].includes(period)){const n=Number(period.replace("days","")),end=new Date(now);end.setDate(end.getDate()-1);const d=new Date(end);d.setDate(d.getDate()-(n-1));from=localDateKey(d);to=localDateKey(end);}else if(period==="thisMonth"){from=localDateKey(new Date(now.getFullYear(),now.getMonth(),1));const end=new Date(now);end.setDate(end.getDate()-1);to=localDateKey(end);}else if(period==="lastMonth"){from=localDateKey(new Date(now.getFullYear(),now.getMonth()-1,1));to=localDateKey(new Date(now.getFullYear(),now.getMonth(),0));}else if(period==="date"){from=to=$("#dateSingle").value||null;}else if(period==="custom"){from=$("#dateFrom").value||null;to=$("#dateTo").value||null;}const hour=$("#hourFilter").value,type=$("#typeFilter").value,search=$("#orderSearch").value.trim().toLowerCase();return allOrders.filter(order=>{const date=new Date(order.created_at),day=localDateKey(date);if(viewingHistory?day>=today:day!==today)return false;if(from&&day<from)return false;if(to&&day>to)return false;if(from&&to&&from>to)return false;if(hour!=="all"&&date.getHours()!==Number(hour))return false;if(type!=="all"&&order.order_type!==type)return false;if(activeFilter==="in-progress"&&!["accepted","preparing"].includes(order.status))return false;if(activeFilter==="ready-completed"&&!["ready","completed"].includes(order.status))return false;if(activeFilter!=="all"&&!["in-progress","ready-completed"].includes(activeFilter)&&order.status!==activeFilter)return false;if(search&&![(order.order_number||""),(order.customer_name||""),(order.customer_phone||"")].some(v=>String(v).toLowerCase().includes(search)))return false;return true;});}
