function renderOrders(){const list=$("#ordersList"),orders=filteredOrders();$("#resultsSummary").textContent=viewingTrash?"Trash · "+orders.length+" deleted orders":viewingHistory?"Order history · "+({all:"All previous dates","7days":"Last 7 days","15days":"Last 15 days","30days":"Last 30 days","90days":"Last 90 days",thisMonth:"This month",lastMonth:"Last month",date:"Selected date",custom:"Custom date range",yesterday:"Yesterday"}[$("#periodFilter").value]||"Previous dates")+" · "+orders.length+" orders":"Today · "+orders.length+" orders";list.replaceChildren();if(!orders.length){const p=document.createElement("p");p.className="empty";p.textContent="No orders match these filters.";list.append(p);return;}orders.forEach(order=>{const card=document.createElement("article");card.className="order-card";const head=document.createElement("div");head.className="order-head";const title=document.createElement("div");const ref=document.createElement("div");ref.className="order-ref";ref.textContent=order.order_number;const time=document.createElement("div");time.className="order-time";time.textContent=dateTime(order.created_at);const elapsed=document.createElement("span");elapsed.className="order-elapsed";elapsed.dataset.timer="";elapsed.dataset.start=order.created_at||"";const finishedAt=order.completed_at||(order.status==="completed"?order.updated_at:"");if(finishedAt)elapsed.dataset.end=finishedAt;elapsed.textContent=formatElapsed(Date.now()-(Date.parse(order.created_at)||Date.now()));title.append(ref,time,elapsed);const badge=document.createElement("span");badge.className="order-status-label status-"+String(order.status||"").toLowerCase();badge.textContent=String(order.status||"").replace(/-/g," ").toUpperCase();head.append(title,badge);card.append(head);const groupRootId=order.parent_order_id||order.id;const groupOrders=allOrders.filter(candidate=>(candidate.parent_order_id||candidate.id)===groupRootId);if(groupOrders.length>1){const groupBox=document.createElement("section");groupBox.className="order-group-link";const groupToggle=document.createElement("button");groupToggle.type="button";groupToggle.className="order-group-toggle";const groupTotal=groupOrders.reduce((sum,candidate)=>sum+Number(candidate.total||0),0);groupToggle.textContent="View linked order group · "+groupOrders.length+" orders · "+money(groupTotal);const groupDetails=document.createElement("div");groupDetails.className="order-group-details";groupDetails.hidden=true;groupOrders.slice().sort((a,b)=>new Date(a.created_at)-new Date(b.created_at)).forEach((member,index)=>{const row=document.createElement("div");row.className="order-group-member";const main=document.createElement("div");const number=document.createElement("strong");number.textContent=(index===0?"Original · ":"Continuation · ")+member.order_number;const meta=document.createElement("small");meta.textContent=dateTime(member.created_at)+" · "+(member.status||"").toUpperCase()+" · "+money(member.total);main.append(number,meta);row.append(main);groupDetails.append(row);});groupToggle.addEventListener("click",()=>{groupDetails.hidden=!groupDetails.hidden;groupToggle.textContent=(groupDetails.hidden?"View":"Hide")+" linked order group · "+groupOrders.length+" orders · "+money(groupTotal);});groupBox.append(groupToggle,groupDetails);card.append(groupBox);}if(order.parent_order_id){const linked=document.createElement("div");linked.className="continuation-badge";linked.textContent="CONTINUATION ORDER";card.append(linked);}const meta=document.createElement("div");meta.className="order-meta";meta.textContent=[order.customer_name,order.customer_phone].filter(Boolean).join(" · ");card.append(meta);const typeBadge=document.createElement("span");typeBadge.className="order-type-badge "+(order.order_type==="dine-in"?"dine-in":"takeaway");typeBadge.textContent=order.order_type==="dine-in"?"DINE IN":"TAKE AWAY";card.append(typeBadge);if(order.order_type==="dine-in"){const table=document.createElement("div");table.className="order-table-highlight";const label=document.createElement("span");label.textContent="TABLE";const number=document.createElement("strong");number.textContent=order.table_number||"—";table.append(label,number);card.append(table);}if(order.parent_order_id){const parent=allOrders.find(x=>x.id===order.parent_order_id);const info=document.createElement("section");info.className="continuation-info";const heading=document.createElement("strong");heading.textContent="Continuation of "+(parent?.order_number||"previous order");info.append(heading);const toggle=document.createElement("button");toggle.type="button";toggle.textContent="View original order";const detail=document.createElement("div");detail.className="continuation-original";detail.hidden=true;if(parent){const parentMeta=document.createElement("div");parentMeta.textContent=dateTime(parent.created_at)+" · "+(parent.status||"").toUpperCase()+" · "+money(parent.total);detail.append(parentMeta);(parent.items||[]).forEach(item=>{const line=document.createElement("div");line.textContent=(item.quantity||1)+" × "+item.name;detail.append(line);});}else{const missing=document.createElement("div");missing.textContent="Original order details are not in the current order list.";detail.append(missing);}toggle.addEventListener("click",()=>{detail.hidden=!detail.hidden;toggle.textContent=detail.hidden?"View original order":"Hide original order";});info.append(toggle,detail);card.append(info);}const items=document.createElement("div");items.className="order-items";(order.items||[]).forEach(item=>{const row=document.createElement("div");row.className="order-item";const name=document.createElement("div");name.className="order-item-name";const heading=document.createElement("div");heading.className="order-item-heading";const quantity=document.createElement("span");quantity.className="order-item-quantity";quantity.textContent=String(item.quantity||1)+" ×";quantity.setAttribute("aria-label","Quantity "+String(item.quantity||1));const description=document.createElement("span");description.className="order-item-description";description.textContent=item.name;heading.append(quantity,description);name.append(heading);if(item.addons?.length){const small=document.createElement("small");small.className="item-addons";small.textContent="ADD-ONS · "+item.addons.map(a=>a.name).join(", ");name.append(small);}if(item.note){const small=document.createElement("small");small.className="item-note";small.textContent="ITEM NOTE · "+item.note;name.append(small);}const price=document.createElement("strong");price.textContent=money((Number(item.unit_price||0)+((item.addons||[]).reduce((s,a)=>s+Number(a.price||0),0)))*Number(item.quantity||1));row.append(name,price);items.append(row);});card.append(items);const total=document.createElement("div");total.className="order-total";total.innerHTML="<span>Total</span><strong>"+money(order.total)+"</strong>";card.append(total);if(order.customer_note){const note=document.createElement("p");note.className="order-note customer-note-panel";note.textContent=order.customer_note;card.append(note);}const actions=document.createElement("div");actions.className="actions"+(order.status==="new"&&!viewingTrash?" has-accept-action":"");if(!viewingTrash){const next={new:[["Accept & Prepare","preparing"],["Reject Order","cancelled"]],accepted:[["Ready & Completed","completed"],["Cancel Order","cancelled"]],preparing:[["Ready & Completed","completed"],["Cancel Order","cancelled"]],ready:[["Mark Completed","completed"]]};(next[order.status]||[]).forEach(([label,status])=>{const b=document.createElement("button");b.className="action"+(["preparing","ready","completed"].includes(status)?" primary-action":"")+(status==="cancelled"?" action-danger":"");if(order.status==="new"&&status==="preparing"){b.classList.add("accept-order-action");b.innerHTML='<span class="accept-check" aria-hidden="true">✓</span><span class="accept-copy"><strong>Accept order</strong><small>Send to kitchen · Start preparation</small></span><span class="accept-arrow" aria-hidden="true">→</span>';b.setAttribute("aria-label","Accept order and send to kitchen");}else{b.textContent=label;}b.addEventListener("click",()=>updateStatus(order.id,status));actions.append(b);});}if(!viewingTrash){const editButton=document.createElement("button");editButton.className="action edit-products-action";editButton.innerHTML='<span aria-hidden="true">✎</span><span>Edit products</span>';editButton.addEventListener("click",()=>editOrderProducts(order));actions.append(editButton);}if(viewingTrash){const restoreButton=document.createElement("button");restoreButton.className="action restore-order";restoreButton.textContent="↶ Restore order";restoreButton.addEventListener("click",async()=>{if(!confirm("Restore "+order.order_number+" to active orders?"))return;try{await request("restore-order",{method:"PATCH",body:{id:order.id}});await loadOrders();}catch(error){$("#dashboardError").textContent=error.message;}});actions.append(restoreButton);}else{const deleteButton=document.createElement("button");deleteButton.className="action delete-order";deleteButton.innerHTML='<span class="delete-order-icon" aria-hidden="true">⌫</span><span>Move to Trash</span>';deleteButton.setAttribute("aria-label","Move order "+order.order_number+" to Trash");deleteButton.title="Move to Trash — can be restored later";deleteButton.addEventListener("click",async()=>{if(!confirm("Move "+order.order_number+" to Trash? You can restore it later from the Trash view."))return;try{await request("delete-order",{method:"PATCH",body:{id:order.id}});await loadOrders();}catch(error){$("#dashboardError").textContent=error.message;}});actions.append(deleteButton);}card.append(actions);list.append(card);});refreshOrderTimers();}
async function updateStatus(id,status){try{await request("update-status",{method:"PATCH",body:{id,status}});await loadOrders();}catch(error){$("#dashboardError").textContent=error.message;}}

async function editOrderProducts(order){
 let items=(order.items||[]).map(item=>({...item,addons:Array.isArray(item.addons)?item.addons:[],item_status:item.item_status||(order.status==="new"?"pending":"preparing"),fulfillment_type:item.fulfillment_type||(order.order_type==="takeaway"?"takeaway":"dine-in")}));
 const dialog=document.createElement("dialog");dialog.className="simple-order-editor";
 const escapeHtml=value=>String(value??"").replace(/[&<>"]/g,ch=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[ch]));
 const draw=()=>{
  dialog.innerHTML='<form method="dialog" class="simple-editor-form"><header><div><h2>Edit order</h2><p>'+escapeHtml(order.order_number)+' · Current total '+money(order.total)+'</p></div><button class="editor-close" value="cancel" aria-label="Close">×</button></header><div class="simple-editor-items">'+items.map((item,index)=>'<section class="simple-editor-item" data-index="'+index+'"><div class="simple-editor-top"><label class="product-name">Product name<input data-field="name" value="'+escapeHtml(item.name)+'" required></label><div class="editor-item-actions"><button type="button" class="editor-cancel-item" data-cancel-item="'+index+'">'+(item.item_status==="cancelled"?"Restore item":"Cancel this item")+'</button><button type="button" class="editor-remove" data-remove="'+index+'">Remove</button></div></div><div class="simple-editor-controls"><label>Quantity<input data-field="quantity" type="number" min="1" max="99" value="'+Number(item.quantity||1)+'"></label><label>Price each (₹)<input data-field="unit_price" type="number" min="0" step="1" value="'+Number(item.unit_price||0)+'"></label><label class="editor-fulfillment">Pack as takeaway (+₹10 each)<input data-field="fulfillment_type" type="checkbox" '+(item.fulfillment_type==="takeaway"?"checked":"")+'> </label><label>Item status<select data-field="item_status"><option value="pending" '+(item.item_status==="pending"?"selected":"")+'>Awaiting acceptance</option><option value="preparing" '+(item.item_status==="preparing"?"selected":"")+'>Preparing</option><option value="cancelled" '+(item.item_status==="cancelled"?"selected":"")+'>Cancelled</option><option value="completed" '+(item.item_status==="completed"?"selected":"")+'>Completed</option></select></label></div>'+(item.addons.length?'<p class="editor-addons">Add-ons kept: '+escapeHtml(item.addons.map(a=>a.name).join(", "))+'</p>':"")+'</section>').join("")+'</div><button type="button" id="editorAddProduct" class="editor-add-button">＋ Add another product</button><div id="editorAddFields" class="editor-add-fields" hidden><label>Product name<input id="newItemName" placeholder="Enter product name"></label><div class="simple-editor-controls"><label>Quantity<input id="newItemQty" type="number" min="1" value="1"></label><label>Price each (₹)<input id="newItemPrice" type="number" min="0" value="0"></label></div><button type="button" id="confirmAddProduct" class="editor-add-button">Add to order</button></div><label class="editor-customer-note">Note for customer (optional)<input id="editorCustomerNote" value="'+escapeHtml(order.customer_note||"")+'" placeholder="e.g. One item is unavailable"></label><div class="simple-editor-total"><span>Updated total</span><strong id="editorTotal"></strong></div><p class="editor-help">Cancelled products are removed from the total. Existing add-ons are kept.</p><p class="error" id="editorError" role="alert"></p><footer><button type="button" class="editor-cancel" id="editorCancel">Cancel</button><button type="button" class="editor-save" id="editorSave">Save changes</button></footer></form>';
  const total=items.reduce((sum,item)=>sum+(item.item_status==="cancelled"?0:Number(item.quantity||1)*(Number(item.unit_price||0)+(item.addons||[]).reduce((a,x)=>a+Number(x.price||0),0))),0)+items.reduce((sum,item)=>sum+(item.item_status==="cancelled"||item.fulfillment_type!=="takeaway"?0:Number(item.quantity||1)*10),0);
  dialog.querySelector("#editorTotal").textContent=money(total);
  dialog.querySelectorAll(".simple-editor-item").forEach(section=>section.querySelectorAll("[data-field]").forEach(input=>input.addEventListener("change",()=>{const item=items[Number(section.dataset.index)],field=input.dataset.field;item[field]=field==="quantity"||field==="unit_price"?Number(input.value):field==="fulfillment_type"?(input.checked?"takeaway":"dine-in"):input.value;updateTotal();})));
  dialog.querySelectorAll("[data-remove]").forEach(button=>button.addEventListener("click",()=>{items.splice(Number(button.dataset.remove),1);draw();}));
  dialog.querySelectorAll("[data-cancel-item]").forEach(button=>button.addEventListener("click",()=>{const item=items[Number(button.dataset.cancelItem)];item.item_status=item.item_status==="cancelled"?"preparing":"cancelled";draw();}));
  dialog.querySelector("#editorAddProduct").addEventListener("click",()=>{dialog.querySelector("#editorAddFields").hidden=false;dialog.querySelector("#newItemName").focus();});
  dialog.querySelector("#confirmAddProduct").addEventListener("click",()=>{const name=dialog.querySelector("#newItemName").value.trim(),price=Number(dialog.querySelector("#newItemPrice").value),quantity=Number(dialog.querySelector("#newItemQty").value);if(!name||price<0||quantity<1){dialog.querySelector("#editorError").textContent="Enter a product name, valid price and quantity.";return;}items.push({name,quantity,unit_price:price,addons:[],note:"",category:"",section:"",item_status:order.status==="new"?"pending":"preparing",fulfillment_type:order.order_type==="takeaway"?"takeaway":"dine-in"});draw();});
  dialog.querySelector("#editorCancel").addEventListener("click",()=>dialog.close());
  dialog.querySelector("#editorSave").addEventListener("click",async()=>{const button=dialog.querySelector("#editorSave");button.disabled=true;button.textContent="Saving…";try{if(!items.length)throw new Error("An order must have at least one product.");await request("edit-order",{method:"PATCH",body:{id:order.id,items,customer_note:dialog.querySelector("#editorCustomerNote").value}});dialog.close();await loadOrders();}catch(error){dialog.querySelector("#editorError").textContent=error.message;button.disabled=false;button.textContent="Save changes";}});
  function updateTotal(){const value=items.reduce((sum,item)=>sum+(item.item_status==="cancelled"?0:Number(item.quantity||1)*(Number(item.unit_price||0)+(item.addons||[]).reduce((a,x)=>a+Number(x.price||0),0))),0)+items.reduce((sum,item)=>sum+(item.item_status==="cancelled"||item.fulfillment_type!=="takeaway"?0:Number(item.quantity||1)*10),0);dialog.querySelector("#editorTotal").textContent=money(value);}
 };
 draw();document.body.append(dialog);dialog.showModal();dialog.addEventListener("close",()=>dialog.remove(),{once:true});
}


/* Responsive sidebar: desktop collapse + mobile slide-out navigation */
(()=>{
 const dashboard=$("#dashboardView"),toggle=$("#sidebarCollapseToggle"),key="tccOrderDeskSidebarCollapsedV1";
 const mobileToggle=$("#mobileNavToggle"),backdrop=$("#mobileNavBackdrop"),sidebar=$("#deskSidebar");
 const closeMobile=()=>{
  dashboard.classList.remove("mobile-nav-open");document.body.classList.remove("mobile-nav-lock");if(backdrop)backdrop.hidden=true;
  mobileToggle?.setAttribute("aria-expanded","false");mobileToggle?.setAttribute("aria-label","Open navigation");
  if(mobileToggle)mobileToggle.textContent="☰";
 };
 const openMobile=()=>{
  dashboard.classList.add("mobile-nav-open");document.body.classList.add("mobile-nav-lock");if(backdrop)backdrop.hidden=false;
  mobileToggle?.setAttribute("aria-expanded","true");mobileToggle?.setAttribute("aria-label","Close navigation");
  if(mobileToggle)mobileToggle.textContent="✕";
 };
 mobileToggle?.addEventListener("click",()=>dashboard.classList.contains("mobile-nav-open")?closeMobile():openMobile());
 backdrop?.addEventListener("click",closeMobile);
 sidebar?.addEventListener("click",e=>{if(e.target.closest("a,button"))closeMobile();});
 document.addEventListener("keydown",e=>{if(e.key==="Escape")closeMobile();});
 window.addEventListener("resize",()=>{if(window.innerWidth>900)closeMobile();});
 if(!dashboard||!toggle)return;
 if(!dashboard||!toggle)return;
 const links=[...document.querySelectorAll(".sidebar-nav .sidebar-link")];
 links.forEach(link=>{const label=link.querySelector("span:not(.sidebar-icon)");if(label)link.title=label.textContent.trim();});
 const logout=$("#logoutButton");if(logout)logout.title="Log out";
 const apply=collapsed=>{
  dashboard.classList.toggle("sidebar-collapsed",collapsed);
  toggle.setAttribute("aria-expanded",String(!collapsed));
  toggle.setAttribute("aria-label",collapsed?"Expand sidebar":"Collapse sidebar");
  toggle.title=collapsed?"Expand sidebar":"Collapse sidebar";
  try{localStorage.setItem(key,collapsed?"1":"0");}catch{}
 };
 let collapsed=false;try{collapsed=localStorage.getItem(key)==="1";}catch{}
 apply(collapsed);
 toggle.addEventListener("click",()=>apply(!dashboard.classList.contains("sidebar-collapsed")));
})();

