const localDay=()=>{const d=new Date(),y=d.getFullYear(),m=String(d.getMonth()+1).padStart(2,"0"),day=String(d.getDate()).padStart(2,"0");return y+"-"+m+"-"+day;};
function setTableHistoryView(open){const view=$("#tableRequestsHistoryView"),main=$("#deskSidebar").nextElementSibling;const orderSections=["#assistancePanel","#stats","#historyTools",".toolbar","#resultsSummary","#dashboardError","#ordersList",".desk-main>footer"];if(open){viewingHistory=false;viewingTrash=false;$("#sidebarTodayLink").classList.remove("active");$("#sidebarHistoryButton").classList.remove("active");$("#sidebarTableRequestsHistoryButton").classList.add("active");$("#sidebarTableRequestsHistoryButton").setAttribute("aria-pressed","true");$("#sidebarHistoryButton").setAttribute("aria-pressed","false");$("#sidebarTodayLink").removeAttribute("aria-current");$("#trashViewButton").classList.remove("trash-active");$("#historyTabs").hidden=true;$("#historyTools").hidden=true;orderSections.forEach(sel=>{const el=document.querySelector(sel);if(el)el.hidden=true;});view.hidden=false;$("#tableHistoryDate").value=$("#tableHistoryDate").value||localDay();tableHistoryOffset=0;loadTableRequestHistory(false);}else{view.hidden=true;orderSections.forEach(sel=>{const el=document.querySelector(sel);if(el)el.hidden=false;});$("#sidebarTableRequestsHistoryButton").classList.remove("active");$("#sidebarTableRequestsHistoryButton").setAttribute("aria-pressed","false");}}
async function loadTableRequestHistory(append){if(tableHistoryBusy)return;tableHistoryBusy=true;const body=$("#tableHistoryRows"),date=$("#tableHistoryDate").value||localDay(),type=$("#tableHistoryType").value;if(!append){tableHistoryOffset=0;body.innerHTML='<tr><td colspan="5">Loading…</td></tr>';}try{const data=await requestTableHistory(date,type,tableHistoryOffset),rows=data.requests||[];if(!append)body.replaceChildren();rows.forEach(r=>{const tr=document.createElement("tr"),received=new Date(r.created_at),attended=r.attended_at?new Date(r.attended_at):null,duration=attended?Math.max(0,Math.floor((attended-received)/1000)):null;const fmt=d=>d.toLocaleTimeString("en-IN",{hour:"numeric",minute:"2-digit",second:"2-digit"});const elapsed=duration===null?"—":duration<60?duration+" sec":Math.floor(duration/60)+" min "+String(duration%60).padStart(2,"0")+" sec";[r.table_number,r.request_type==="bill"?"Request Bill":"Call Staff",fmt(received),attended?fmt(attended):"—",elapsed].forEach((v,i)=>{const td=document.createElement("td");td.textContent=v;if(i===1)td.className=r.request_type==="bill"?"table-history-bill":"table-history-staff";tr.append(td);});body.append(tr);});if(!rows.length&&!append)body.innerHTML='<tr><td colspan="5">No completed table requests for this date.</td></tr>';tableHistoryHasMore=rows.length===50;tableHistoryOffset+=rows.length;$("#tableHistoryOlder").disabled=!tableHistoryHasMore;$("#tableHistorySummary").textContent=rows.length||append?("Showing "+tableHistoryOffset+" completed requests · "+date):"No completed requests · "+date;}catch(e){if(!append)body.innerHTML='<tr><td colspan="5">Unable to load history. Please retry.</td></tr>';$("#tableHistorySummary").textContent=e.message;}finally{tableHistoryBusy=false;}}
