function renderAssistance(){const pending=assistanceRows.filter(r=>r.status==="pending");function renderQueue(type,listId,countId,emptyMessage){const rows=pending.filter(r=>(r.request_type==="bill"?"bill":"staff")===type),list=$("#"+listId);$("#"+countId).textContent=rows.length+" pending";list.replaceChildren();if(!rows.length){const p=document.createElement("p");p.className="assistance-empty";p.textContent=emptyMessage;list.append(p);return;}rows.forEach(r=>{const card=document.createElement("article");card.className="assistance-card assistance-card-"+type;const info=document.createElement("div"),message=document.createElement("strong"),time=document.createElement("span");message.textContent=type==="bill"?"Bill required for table no "+r.table_number+".":"Staff requested for table no "+r.table_number+".";time.textContent=dateTime(r.created_at)+" · "+Math.max(0,Math.floor((Date.now()-Date.parse(r.created_at))/60000))+" min waiting";info.append(message,time);const done=document.createElement("button");done.type="button";done.className="assistance-attend";done.textContent="✓ Attended";done.setAttribute("aria-label","Mark "+type+" request for table "+r.table_number+" attended");done.addEventListener("click",async()=>{done.disabled=true;done.textContent="Updating…";try{await request("attend-table-assistance",{method:"PATCH",body:{id:r.id}});await loadAssistance();}catch(e){done.disabled=false;done.textContent="✓ Attended";alert(e.message);}});card.append(info,done);list.append(card);});}renderQueue("staff","staffAssistanceList","staffAssistanceCount","No staff requests.");renderQueue("bill","billAssistanceList","billAssistanceCount","No bill requests.");}

(function(){const nav=document.getElementById("sidebarMenuUpdatesButton"),view=document.getElementById("menuUpdatesView");if(!nav||!view)return;const $=id=>document.getElementById(id),sels=["header.topbar","#tableRequestsHistoryView","#historyTabs","#assistancePanel","#stats","#historyTools",".toolbar","#resultsSummary","#dashboardError","#ordersList",".desk-main>footer"];let catalog=[],states=new Map(),busy=false;const esc=s=>String(s??"").replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c])),clean=s=>(s||"").replace(/\s+/g," ").trim(),key=(c,n)=>(c+"|"+n).toLowerCase();async function load(){$("menuUpdatesError").textContent="";$("menuUpdatesList").innerHTML="<p>Loading…</p>";try{const [mr,st]=await Promise.all([fetch("menu.html",{cache:"no-store"}),request("menu-availability-admin")]);if(!mr.ok)throw Error("Could not load the customer menu.");const doc=new DOMParser().parseFromString(await mr.text(),"text/html");catalog=[...doc.querySelectorAll(".menu-page .m-item")].map(card=>{const h=card.querySelector("h3"),c=h?.cloneNode(true);c?.querySelectorAll(".tcc-bestseller-badge,.tcc-new-arrival-badge,.food-badge,.availability-status,[class*='bestseller'],[class*='best-seller']").forEach(x=>x.remove());const name=clean(c?.textContent||h?.textContent),category=clean(card.closest(".menu-group")?.getAttribute("data-group")||"Menu"),section=clean(card.closest(".menu-section")?.querySelector("h2")?.textContent||"");return{name,category,section,product_key:key(category,name)};}).filter(x=>x.name);states=new Map((st.items||[]).map(x=>[x.product_key,x]));$("menuUpdatesCategory").innerHTML='<option value="all">All categories</option>'+[...new Set(catalog.map(x=>x.category))].sort().map(x=>'<option value="'+esc(x)+'">'+esc(x)+'</option>').join("");render();}catch(e){$("menuUpdatesError").textContent=e.message||"Unable to load menu.";$("menuUpdatesList").innerHTML="";}}function render(){const q=$("menuUpdatesSearch").value.trim().toLowerCase(),cat=$("menuUpdatesCategory").value,availability=$("menuUpdatesAvailability").value,rows=catalog.filter(x=>(cat==="all"||x.category===cat)&&(availability==="all"||(states.get(x.product_key)?.availability||"available")===availability)&&(!q||(x.name+" "+x.category+" "+x.section).toLowerCase().includes(q)));$("menuUpdatesSummary").textContent=rows.length+" of "+catalog.length+" products";$("menuUpdatesList").innerHTML=rows.map(x=>{const s=states.get(x.product_key)||{},a=s.availability||"available";return'<article class="menu-update-card" data-key="'+esc(x.product_key)+'"><div class="menu-update-info"><strong>'+esc(x.name)+'</strong><small>'+esc(x.category)+' · '+esc(x.section)+'</small><div class="menu-update-status"><span class="'+(a==="sold_out"?"is-sold":"is-available")+'">'+(a==="sold_out"?"Sold Out":"Available")+'</span></div></div><div class="menu-update-actions"><button data-action="availability" data-value="'+(a==="sold_out"?"available":"sold_out")+'">'+(a==="sold_out"?"Mark Available":"Mark Sold Out")+'</button></div></article>';}).join("")||"<p>No matching products.</p>";}async function update(x,val,b){if(busy)return;busy=true;b.disabled=true;b.textContent="Saving…";try{const r=await request("menu-availability",{method:"PATCH",body:{...x,availability:val}});if(!r.item)throw Error("Update was not confirmed.");states.set(x.product_key,r.item);render();}catch(e){$("menuUpdatesError").textContent=e.message||"Could not save.";b.disabled=false;b.textContent=val==="sold_out"?"Mark Sold Out":"Mark Available";}finally{busy=false;}}nav.addEventListener("click",()=>{view.hidden=false;sels.forEach(s=>{const e=document.querySelector(s);if(e)e.hidden=true;});document.querySelectorAll("#sidebarTodayLink,#sidebarHistoryButton,#sidebarTableRequestsHistoryButton,#trashViewButton").forEach(x=>x.classList.remove("active","trash-active"));document.querySelector("#sidebarTodayLink").removeAttribute("aria-current");nav.classList.add("active");nav.setAttribute("aria-pressed","true");load();});document.querySelector(".sidebar-nav").addEventListener("click",e=>{const target=e.target.closest("#sidebarTodayLink,#sidebarHistoryButton,#sidebarTableRequestsHistoryButton,#trashViewButton,#sidebarPreferencesButton");if(!target)return;view.hidden=true;if(target.id!=="sidebarTableRequestsHistoryButton"){sels.filter(s=>s!=="#tableRequestsHistoryView").forEach(s=>{const x=document.querySelector(s);if(x)x.hidden=false;});$("#historyTabs").hidden=!viewingHistory||viewingTrash;$("#historyTools").hidden=!viewingHistory||viewingTrash;$("#filters").hidden=viewingTrash;}nav.classList.remove("active");nav.setAttribute("aria-pressed","false");});$("menuUpdatesRefresh").addEventListener("click",load);$("menuUpdatesSearch").addEventListener("input",render);$("menuUpdatesCategory").addEventListener("change",render);$("menuUpdatesAvailability").addEventListener("change",render);$("menuUpdatesList").addEventListener("click",e=>{const b=e.target.closest("button[data-action='availability']");if(!b)return;const x=catalog.find(i=>i.product_key===b.closest(".menu-update-card")?.dataset.key);if(x)update(x,b.dataset.value,b);});})();